async def act(page):
    import re
    import math
    import asyncio

    # There are no knowledge-base helper functions provided for this task, so none are used.

    # 1) Navigate to Manage Products (use relative goto)
    await page.goto("/index.php/admin/catalog_product/")
    await page.wait_for_load_state("networkidle")
    await asyncio.sleep(0.5)

    # 2) Try to filter by Name = 'Desiree' if a Name textbox exists to narrow results
    try:
        name_field = page.get_by_role("textbox", name="Name")
        if await name_field.count() > 0:
            await name_field.fill("Desiree")
            await name_field.press("Enter")
            await page.wait_for_load_state("networkidle")
            await asyncio.sleep(0.5)
    except Exception:
        # proceed even if filtering is not possible
        pass

    # 3) Locate the product row containing Desiree + Black + XS (progressively relaxed)
    rows = page.get_by_role("row")

    candidate = rows.filter(has=page.get_by_text("Desiree")).filter(has=page.get_by_text("Black")).filter(has=page.get_by_text("XS")).first()
    if await candidate.count() == 0:
        candidate = rows.filter(has=page.get_by_text("Desiree")).filter(has=page.get_by_text("Black")).first()
    if await candidate.count() == 0:
        candidate = rows.filter(has=page.get_by_text("Desiree")).first()

    if await candidate.count() == 0:
        raise Exception("Could not locate product row for Desiree black fitness t-shirt (XS)")

    # 4) Open Edit for the selected product row using the full path through the row
    try:
        await candidate.get_by_role("link", name="Edit").click()
    except Exception:
        try:
            await candidate.get_by_role("link").first.click()
        except Exception:
            try:
                await candidate.get_by_role("button", name="Edit").click()
            except Exception:
                raise Exception("Could not click Edit control for the product row")

    # Wait for the product edit page to load
    await page.wait_for_load_state("networkidle")
    await asyncio.sleep(0.5)

    # 5) Locate the Price input (try several accessible strategies)
    price_input = None
    try:
        p = page.get_by_role("textbox", name="Price")
        if await p.count() > 0:
            price_input = p
    except Exception:
        price_input = None

    if price_input is None:
        try:
            p = page.get_by_role("spinbutton", name="Price")
            if await p.count() > 0:
                price_input = p
        except Exception:
            price_input = None

    if price_input is None:
        try:
            p = page.get_by_label("Price")
            if await p.count() > 0:
                price_input = p
        except Exception:
            price_input = None

    if price_input is None or await price_input.count() == 0:
        raise Exception("Price input field not found on product edit page")

    # 6) Read current price
    current_price_str = await price_input.input_value()
    if not current_price_str:
        try:
            current_price_str = await price_input.inner_text()
        except Exception:
            current_price_str = ""

    if not current_price_str:
        raise Exception("Could not read current price value")

    # Normalize and extract numeric portion
    normalized = current_price_str.strip().replace('$', '').replace(',', '')
    m = re.search(r"(\d+(?:\.\d+)?)", normalized)
    if not m:
        raise Exception(f"Failed to parse price from '{current_price_str}'")

    current_price = float(m.group(1))

    # 7) Increase by 37% and round to 2 decimals
    new_price = current_price * 1.37
    new_price_rounded = round(new_price + 1e-9, 2)

    # Fill the new price
    await price_input.fill(f"{new_price_rounded:.2f}")

    # 8) Save the product. Use full path when possible (Save inside a form), otherwise fallback to page-level Save.
    try:
        form_locator = page.get_by_role("form").first
        if await form_locator.count() > 0:
            await form_locator.get_by_role("button", name="Save").click()
            return
    except Exception:
        pass

    # Fallback: click any Save button on the page (this will navigate away and is the last action)
    await page.get_by_role("button", name="Save").first.click()

